import {AppError,roleAllows,scopeAllows,PERMISSIONS} from '@crew/shared';
export function createPermissions(ctx) {
  const {db}=ctx;
  const deny=message=>{throw new AppError('FORBIDDEN',message,403);};
  const membership=(userId,orgId)=>db.prepare('SELECT * FROM memberships WHERE user_id=? AND org_id=?').get(userId,orgId)??null;
  function scope(req,permission) {
    if (!req.user) throw new AppError('UNAUTHENTICATED','Please sign in',401);
    if (!PERMISSIONS.includes(permission)) deny('Unknown permission');
    if (req.auth?.kind==='token'&&!scopeAllows(req.auth.scopes,permission)) deny('API token lacks '+permission+' scope');
    return true;
  }
  function canOrg(userId,orgId,permission='org:read') {
    const member=membership(userId,orgId);
    return Boolean(member&&roleAllows(member.role,permission));
  }
  function assertOrg(req,orgId,permission='org:read') {
    scope(req,permission);
    const member=membership(req.user.id,orgId);
    if (!member||!roleAllows(member.role,permission)) deny('Organization permission denied');
    return member;
  }
  function project(projectId) {
    if (!db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='projects'").get()) throw new AppError('NOT_FOUND','Project not found',404);
    const row=db.prepare('SELECT * FROM projects WHERE id=?').get(projectId);
    if (!row) throw new AppError('NOT_FOUND','Project not found',404);
    return row;
  }
  function canProject(userId,projectId,permission='project:read') {
    const row=project(projectId);
    const member=membership(userId,row.org_id);
    if (!member||!roleAllows(member.role,permission,{project:true})) return false;
    return member.role!=='guest'||Boolean(db.prepare('SELECT 1 FROM project_guests WHERE project_id=? AND user_id=?').get(projectId,userId));
  }
  function assertProject(req,projectId,permission='project:read') {
    scope(req,permission);
    const row=project(projectId);
    if (!canProject(req.user.id,projectId,permission)) deny('Project permission denied');
    return row;
  }
  function assertSelf(req,userId=req.user?.id,permission='self:read') {
    scope(req,permission);
    if (userId!==req.user.id) deny('This action belongs to another account');
    return req.user;
  }
  function projectIds(userId,orgId) {
    const member=membership(userId,orgId);
    if (!member) return [];
    if (!db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='projects'").get()) return [];
    if (member.role==='guest') return db.prepare('SELECT p.id FROM projects p JOIN project_guests g ON p.id=g.project_id WHERE p.org_id=? AND g.user_id=? ORDER BY p.id').all(orgId,userId).map(r=>r.id);
    return db.prepare('SELECT id FROM projects WHERE org_id=? ORDER BY id').all(orgId).map(r=>r.id);
  }
  return {scope,membership,canOrg,assertOrg,canProject,assertProject,assertSelf,projectIds};
}
export function requirePermission(ctx,permission,resolve) {
  return (req,res,next)=>{
    try {const target=resolve(req);if(target.projectId)ctx.permissions.assertProject(req,target.projectId,permission);else if(target.orgId)ctx.permissions.assertOrg(req,target.orgId,permission);else ctx.permissions.assertSelf(req,target.userId,permission);next();} catch(error){next(error);}
  };
}

import {test,beforeEach,afterEach} from 'node:test';
import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import {createPermissions} from '../src/http/middleware/permissions.js';
let db,p;
beforeEach(()=>{
  db=new DatabaseSync(':memory:');
  db.exec(`CREATE TABLE memberships (org_id TEXT,user_id TEXT,role TEXT);
    CREATE TABLE projects (id TEXT,org_id TEXT);
    CREATE TABLE project_guests (project_id TEXT,user_id TEXT);
    INSERT INTO memberships VALUES ('a','owner','owner'),('a','admin','admin'),('a','member','member'),('a','guest','guest'),('b','foreign','owner');
    INSERT INTO projects VALUES ('a1','a'),('a2','a'),('b1','b');
    INSERT INTO project_guests VALUES ('a1','guest');`);
  p=createPermissions({db});
});
afterEach(()=>db.close());
const req=(id,scopes=null)=>({user:{id},auth:scopes?{kind:'token',scopes}:{kind:'session'}});
test('project guest may read and comment only on granted project',()=>{assert(p.canProject('guest','a1'));assert(p.canProject('guest','a1','comment:write'));assert.equal(p.canProject('guest','a2'),false);assert.equal(p.canProject('guest','a1','issue:write'),false);});
test('members may work in all organization projects but not manage projects',()=>{assert(p.canProject('member','a2','issue:write'));assert.equal(p.canProject('member','a2','project:manage'),false);});
test('admins and owners manage projects with explicit organization boundary',()=>{assert(p.canProject('admin','a1','project:manage'));assert(p.canProject('owner','a2','project:manage'));assert.equal(p.canProject('foreign','a1'),false);});
test('accessible project ids filter guests and outsiders',()=>{assert.deepEqual(p.projectIds('guest','a'),['a1']);assert.deepEqual(p.projectIds('owner','a'),['a1','a2']);assert.deepEqual(p.projectIds('foreign','a'),[]);});
test('assertProject returns raw project and rejects missing ids',()=>{assert.equal(p.assertProject(req('owner'),'a1').org_id,'a');assert.throws(()=>p.assertProject(req('owner'),'missing'),e=>e.status===404);});
test('API scope and user role must both permit project actions',()=>{assert.throws(()=>p.assertProject(req('owner',['project:read']),'a1','issue:write'),e=>e.status===403);assert.throws(()=>p.assertProject(req('guest',['*']),'a1','issue:write'),e=>e.status===403);assert.equal(p.assertProject(req('member',['issue:*']),'a1','issue:write').id,'a1');});
test('organization assertion rejects unauthorized and scoped access',()=>{assert.throws(()=>p.assertOrg(req('foreign'),'a'),e=>e.status===403);assert.throws(()=>p.assertOrg(req('owner',['self:*']),'a'),e=>e.status===403);assert.equal(p.assertOrg(req('admin',['org:*']),'a','org:manage').role,'admin');});
test('self assertion rejects other users and unauthenticated requests',()=>{assert.throws(()=>p.assertSelf(req('owner'),'member'),e=>e.status===403);assert.throws(()=>p.scope({user:null},'self:read'),e=>e.status===401);assert.equal(p.assertSelf(req('owner',['self:read'])).id,'owner');});
test('unknown permission never passes a wildcard token',()=>{assert.throws(()=>p.scope(req('owner',['*']),'root:admin'),e=>e.status===403);assert.equal(p.canOrg('owner','a','unknown'),false);assert.throws(()=>p.scope(req('owner'),'unknown'),e=>e.status===403);});

import {h} from 'preact';
import {useState,useEffect} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading,DataTable,useLoad} from '../../components/ui.jsx';
import {canManage,roleOptions,organizationPath} from './state.js';
export function OrganizationLinks({id}) {
  return <nav className="subnav" aria-label="Organization settings">{['members','teams'].map(tab=><a href={'#'+organizationPath(id,tab)}>{tab}</a>)}</nav>;
}
export function Organizations({api,store,navigate}) {
  const list=useLoad(()=>api.get('/orgs'),[]);
  const [name,setName]=useState('');
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState(null);
  async function create(event) {
    event.preventDefault();setBusy(true);setError(null);
    try {const result=await api.post('/orgs',{name});store.set({organization:result.organization});navigate(organizationPath(result.organization.id));}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  return <Page title="Organizations"><p>Choose the organization whose projects and people you want to manage.</p><Notice error={error??list.error}/>{list.loading?<Loading/>:<DataTable items={list.data?.items} empty="You have no organizations yet. Create one below." columns={[{key:'name',label:'Organization',render:org=><a href={'#'+organizationPath(org.id)} onClick={()=>store.set({organization:org})}>{org.name}</a>},{key:'role',label:'Your role'}]}/>}<h2>Create organization</h2><form onSubmit={create}><Field label="Organization name" value={name} required maxLength={120} onInput={e=>setName(e.target.value)} error={error?.details?.name}/><Button busy={busy}>Create organization</Button></form></Page>;
}
export function Members({params,api,store}) {
  const id=params.orgId;
  const data=useLoad(()=>Promise.all([api.get('/orgs/'+id),api.get('/orgs/'+id+'/members')]),[id]);
  const [error,setError]=useState(null);
  const [busy,setBusy]=useState(false);
  const [name,setName]=useState('');
  const [userId,setUserId]=useState('');
  const [role,setRole]=useState('member');
  const org=data.data?.[0]?.organization;
  async function action(fn){setBusy(true);setError(null);try{await fn();data.reload();}catch(error){setError(error);}finally{setBusy(false);}}
  async function rename(event){event.preventDefault();await action(async()=>{const result=await api.patch('/orgs/'+id,{name});store.set({organization:result.organization});setName('');});}
  async function add(event){event.preventDefault();await action(()=>api.post('/orgs/'+id+'/members',{userId,role}));}
  return <Page title={org?org.name+' · Members':'Members'}><OrganizationLinks id={id}/><Notice error={error??data.error}/>{data.loading?<Loading/>:<><p>Your role: <strong>{org?.role}</strong>. Invite a new colleague from Invitations, or add an existing account by id.</p><DataTable items={data.data?.[1]?.items} keyField="userId" columns={[{key:'name',label:'Name'},{key:'email',label:'Email'},{key:'role',label:'Role',render:member=>canManage(org?.role)&&!(member.role==='owner'&&org.role!=='owner')?<select aria-label={'Role for '+member.name} disabled={busy} value={member.role} onChange={e=>action(()=>api.patch('/orgs/'+id+'/members/'+member.userId,{role:e.target.value}))}>{roleOptions(org.role).map(role=><option value={role}>{role}</option>)}</select>:member.role},{key:'remove',label:'Membership',render:member=>canManage(org?.role)?<Button busy={busy} onClick={()=>action(()=>api.delete('/orgs/'+id+'/members/'+member.userId))}>Remove {member.name}</Button>:null}]}/>{canManage(org?.role)&&<><h2>Add existing account</h2><form onSubmit={add}><Field label="User id" value={userId} required onInput={e=>setUserId(e.target.value)}/><Field label="Role"><select value={role} onChange={e=>setRole(e.target.value)}>{roleOptions(org.role).map(role=><option>{role}</option>)}</select></Field><Button busy={busy}>Add member</Button></form><h2>Rename organization</h2><form onSubmit={rename}><Field label="New name" placeholder={org?.name} value={name} required maxLength={120} onInput={e=>setName(e.target.value)}/><Button busy={busy}>Save organization name</Button></form></>}</>}</Page>;
}
export function Teams({params,api}) {
  const id=params.orgId;
  const data=useLoad(()=>Promise.all([api.get('/orgs/'+id),api.get('/orgs/'+id+'/teams')]),[id]);
  const [values,setValues]=useState({name:'',description:''});
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState(null);
  async function create(event){event.preventDefault();setBusy(true);setError(null);try{await api.post('/orgs/'+id+'/teams',values);setValues({name:'',description:''});data.reload();}catch(error){setError(error);}finally{setBusy(false);}}
  const org=data.data?.[0]?.organization;
  return <Page title={org?org.name+' · Teams':'Teams'}><OrganizationLinks id={id}/><Notice error={error??data.error}/>{data.loading?<Loading/>:<DataTable items={data.data?.[1]?.items} empty="No teams yet." columns={[{key:'name',label:'Team',render:team=><a href={'#/teams/'+team.id}>{team.name}</a>},{key:'description',label:'Description'}]}/>} {canManage(org?.role)&&<><h2>Create team</h2><form onSubmit={create}><Field label="Team name" required maxLength={120} value={values.name} onInput={e=>setValues({...values,name:e.target.value})}/><Field label="Description"><textarea value={values.description} maxLength={2000} onInput={e=>setValues({...values,description:e.target.value})}/></Field><Button busy={busy}>Create team</Button></form></>}</Page>;
}
export function TeamDetail({params,api,navigate}) {
  const id=params.teamId;
  const data=useLoad(async()=>{const team=(await api.get('/teams/'+id)).team;return {team,org:(await api.get('/orgs/'+team.orgId)).organization,members:(await api.get('/teams/'+id+'/members')).items,choices:(await api.get('/orgs/'+team.orgId+'/members')).items};},[id]);
  const [name,setName]=useState('');
  const [description,setDescription]=useState('');
  const [userId,setUserId]=useState('');
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState(null);
  async function action(fn){setBusy(true);setError(null);try{await fn();data.reload();}catch(error){setError(error);}finally{setBusy(false);}}
  const team=data.data?.team;
  useEffect(()=>{if(team){setName(team.name);setDescription(team.description);}},[team?.id]);
  const manage=canManage(data.data?.org.role);
  const available=data.data?.choices.filter(member=>!data.data.members.some(existing=>existing.userId===member.userId))??[];
  return <Page title={team?.name??'Team'}><Notice error={error??data.error}/>{data.loading?<Loading/>:team&&<><OrganizationLinks id={team.orgId}/><p>{team.description||'No description.'}</p><DataTable items={data.data.members} keyField="userId" empty="This team has no members." columns={[{key:'name',label:'Member'},{key:'email',label:'Email'},{key:'role',label:'Organization role'},{key:'remove',label:'Actions',render:member=>manage&&<Button busy={busy} onClick={()=>action(()=>api.delete('/teams/'+id+'/members/'+member.userId))}>Remove {member.name}</Button>}]}/>{manage&&<><h2>Add team member</h2>{available.length?<form onSubmit={e=>{e.preventDefault();action(()=>api.post('/teams/'+id+'/members',{userId:userId||available[0].userId}));}}><Field label="Organization member"><select value={userId} onChange={e=>setUserId(e.target.value)}><option value="">Choose a member</option>{available.map(member=><option value={member.userId}>{member.name} · {member.email}</option>)}</select></Field><Button busy={busy}>Add to team</Button></form>:<Empty>Every organization member is already on this team.</Empty>}<h2>Edit team</h2><form onSubmit={e=>{e.preventDefault();action(()=>api.patch('/teams/'+id,{name,description}));}}><Field label="Name" required placeholder={team.name} value={name} maxLength={120} onInput={e=>setName(e.target.value)}/><Field label="Description"><textarea placeholder={team.description} value={description} maxLength={2000} onInput={e=>setDescription(e.target.value)}/></Field><Button busy={busy}>Save team</Button></form><Button busy={busy} onClick={()=>action(async()=>{await api.delete('/teams/'+id);navigate(organizationPath(team.orgId,'teams'));})}>Delete team</Button></>}</>}</Page>;
}

import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
export async function smoke(ctx) {
  const {api,request,signup,check,ids}=ctx;
  await check('people organization and team persist with owner membership',async()=>{
    const organization=(await api('POST','/orgs',{name:'Acceptance Crew'})).organization;
    ids.orgId=organization.id;
    assert.equal(organization.role,'owner');
    const renamed=(await api('PATCH','/orgs/'+ids.orgId,{name:'Acceptance Team'})).organization;
    assert.equal(renamed.name,'Acceptance Team');
    const team=(await api('POST','/orgs/'+ids.orgId+'/teams',{name:'Delivery',description:'Acceptance team'})).team;
    ids.teamId=team.id;
    assert.equal(team.orgId,ids.orgId);
    const owner=ctx.clients.owner.user;
    await api('POST','/teams/'+ids.teamId+'/members',{userId:owner.id});
    const members=(await api('GET','/teams/'+ids.teamId+'/members')).items;
    assert.equal(members[0].userId,owner.id);
  });
  await check('people member and guest roles enforce administrative denials',async()=>{
    const suffix=Date.now();
    const member=await signup('member',{name:'Acceptance Member',email:`member-${suffix}@crew.test`,password:'acceptance member password'});
    const guest=await signup('guest',{name:'Acceptance Guest',email:`guest-${suffix}@crew.test`,password:'acceptance guest password'});
    await api('POST','/orgs/'+ids.orgId+'/members',{userId:member.id,role:'member'});
    await api('POST','/orgs/'+ids.orgId+'/members',{userId:guest.id,role:'guest'});
    await api('POST','/teams/'+ids.teamId+'/members',{userId:member.id});
    assert.equal((await request('PATCH','/orgs/'+ids.orgId,{name:'Denied'},{actor:'member'})).status,403);
    assert.equal((await request('POST','/orgs/'+ids.orgId+'/teams',{name:'Denied'},{actor:'guest'})).status,403);
    const owner=ctx.clients.owner.user;
    assert.equal((await request('PATCH','/orgs/'+ids.orgId+'/members/'+owner.id,{role:'member'})).status,409);
  });
}
export async function restart(ctx) {
  await ctx.check('people organization team and roles survive restart',async()=>{
    const organization=(await ctx.api('GET','/orgs/'+ctx.ids.orgId)).organization;
    assert.equal(organization.name,'Acceptance Team');
    const team=(await ctx.api('GET','/teams/'+ctx.ids.teamId)).team;
    assert.equal(team.name,'Delivery');
    const members=(await ctx.api('GET','/orgs/'+ctx.ids.orgId+'/members')).items;
    assert(members.some(m=>m.userId===ctx.clients.guest.user.id&&m.role==='guest'));
    assert(members.some(m=>m.userId===ctx.clients.member.user.id&&m.role==='member'));
    const teamMembers=(await ctx.api('GET','/teams/'+ctx.ids.teamId+'/members')).items;
    assert(teamMembers.some(m=>m.userId===ctx.clients.member.user.id));
  });
}
export async function audit({checks}) {
  const permissions=await readFile('docs/api-people.md','utf8');
  assert(permissions.includes('assertProject')&&permissions.includes('project_guests'));
  assert(permissions.includes('outbox(id,org_id,user_id,kind,to_email,subject,text_body,payload_json,created_at,sent_at)'));
  checks.push({name:'People M1 permission/outbox contract documented; later routes require successor audit',ok:true});
}
